use std::{sync::{Arc,Mutex,OnceLock,Weak,atomic::{AtomicBool,Ordering}},thread,time::Duration};use super::{csdm_analysis::Analyses,cli_transport::{Hub,CliListener},scheduler_owner::Owner};use serde_json::{json,Value};
pub struct LiveService{pub hub:Arc<Hub>,owner:Owner,listener:Option<CliListener>}
impl LiveService{
 pub fn with_handler(state:Arc<Mutex<Analyses>>,order:Arc<Mutex<()>>,checksums:impl Fn(&AtomicBool)->Result<Vec<String>,String>+Send+Sync+'static,resolve:impl Fn(&str,&AtomicBool)->Result<Value,String>+Send+Sync+'static,renderer:impl Fn(Value)->Result<(),String>+Send+Sync+'static,mut drive:impl FnMut(&Hub,&AtomicBool)->Result<(),String>+Send+'static)->Result<Self,String>{
  let binding:Arc<OnceLock<Weak<Hub>>>=Arc::new(OnceLock::new());let slot=binding.clone();let owner=Owner::start(move|cancel|{let hub=slot.get().and_then(Weak::upgrade).ok_or("CLI hub unavailable")?;while !cancel.load(Ordering::Acquire){match hub.reconcile_closed(){Ok(())=>return drive(&hub,cancel),Err(error)=>{hub.record_issue(format!("close reconciliation failed: {error}"));thread::sleep(Duration::from_millis(100))}}}Ok(())});
  let hub=Arc::new(Hub::from_handler(state,order,checksums,resolve,owner.wake_handle(),renderer));binding.set(Arc::downgrade(&hub)).map_err(|_|"CLI hub binding failed")?;Ok(Self{hub,owner,listener:None})
 }
 #[cfg(test)] pub fn new(state:Arc<Mutex<Analyses>>,order:Arc<Mutex<()>>,drive:impl FnMut(&Hub,&AtomicBool)->Result<(),String>+Send+'static)->Result<Self,String>{Self::with_handler(state,order,|_|Ok(vec![]),|_,_|Ok(json!({})),|_|Ok(()),drive)}
 pub fn start_listener(&mut self,listener:std::net::TcpListener,capacity:usize)->Result<(),String>{if self.listener.is_some(){return Err("CLI listener already started".into())}self.listener=Some(CliListener::start(listener,self.hub.clone(),capacity)?);Ok(())}
 pub fn shutdown(&mut self,timeout:Duration)->Result<(),String>{let admission=self.hub.stop_admission(timeout);let listener=if let Some(listener)=self.listener.as_mut(){let result=listener.shutdown(timeout);if !listener.is_stopped(){return Err(format!("listener shutdown unconfirmed: {result:?}; admission: {admission:?}"))}result}else{Ok(())};if let Err(error)=admission{return Err(format!("admission shutdown unconfirmed: {error}; listener: {listener:?}"))}let peers=self.hub.peer_count();if !matches!(peers,Ok(0)){return Err(format!("CLI peers unconfirmed: {peers:?}; listener: {listener:?}; owner not stopped"))}let requests=self.hub.join_request_workers(timeout);let quiescent=self.hub.request_workers_quiescent();if !matches!(quiescent,Ok(true)){return Err(format!("request worker shutdown unconfirmed: {quiescent:?}; requests: {requests:?}; listener: {listener:?}"))}let owner=self.owner.shutdown(timeout);if !self.owner.is_stopped(){return Err(format!("owner shutdown unconfirmed: {owner:?}; listener: {listener:?}; requests: {requests:?}"))}let renderer=self.hub.shutdown_renderer(timeout);let issues=self.hub.delivery_issues();match (listener,requests,owner,renderer,issues){(Ok(()),Ok(()),Ok(()),Ok(()),Ok(v)) if v.is_empty()=>Ok(()),(a,r,b,c,d)=>Err(format!("listener: {a:?}; requests: {r:?}; owner: {b:?}; renderer: {c:?}; delivery: {d:?}"))}}
}
